type ApprovalCheck={tab:string;title:string;detail:string;done:boolean};
function approvalChecks(contract:Contract,hotel:Hotel):ApprovalCheck[]{
 const ratesDone=contract.rates.length>0&&contract.rates.every(r=>r.checked&&r.amount!==null&&!!r.source.trim());
 const eventsDone=contract.eventPolicyConfirmed&&contract.events.every(e=>{
  const detailed=e.basis!==undefined||e.through!==undefined||e.name!==undefined;
  const roomBased=(e.basis||'person_once').startsWith('room_');
  return e.checked&&!!e.source.trim()&&(!detailed||!!e.name?.trim()&&!!e.page)&&(roomBased?e.roomAmount!==null&&e.roomAmount!==undefined:e.adult!==null);
 });
 const mealRowsDone=contract.meals.every(m=>m.checked&&!!m.unit.trim()&&(m.adult!==null||m.child!==null));
 const mealsDone=mealRowsDone&&contract.boards.every(b=>b.checked)&&contract.children.every(c=>c.checked&&c.amount!==null);
 const offersDone=(contract.offers||[]).every(o=>o.checked)&&(!(contract.offers||[]).length||contract.offerPolicyConfirmed);
 const upgradesDone=(contract.upgrades||[]).every(u=>u.checked&&u.amount!==null&&!!u.source.trim());
 const questionsDone=contract.issues.every(i=>!!i.resolution.trim());
 return [
  {tab:'Hotel',title:'Hotel details',detail:hotel.name.trim()&&(!hotel.stars||!!hotel.starSource.trim())?'Hotel name and any star source are set.':'Check the hotel name and source for any star rating.',done:!!hotel.name.trim()&&(!hotel.stars||!!hotel.starSource.trim())},
  {tab:'Rates',title:'Currency and rate basis',detail:contract.currency&&contract.unitConfirmed&&contract.nightlyConfirmed?'Currency, room charging and date bands confirmed.':'Choose currency and confirm the rate unit and date bands.',done:!!contract.currency&&contract.unitConfirmed&&contract.nightlyConfirmed},
  {tab:'Rates',title:'Room rates',detail:`${contract.rates.filter(r=>r.checked&&r.amount!==null&&!!r.source.trim()).length} of ${contract.rates.length} rates checked against the PDF.`,done:ratesDone},
  {tab:'Meals',title:'Meal and child rules',detail:mealsDone?`Meal prices, changes and child charges checked${contract.meals.length?` (${contract.meals.length} separate meal prices)`:''}.`:`Check separate meal prices (${contract.meals.filter(m=>m.checked&&!!m.unit.trim()&&(m.adult!==null||m.child!==null)).length} of ${contract.meals.length}), meal changes and child charges.`,done:mealsDone},
  {tab:'Rules',title:'Special dates',detail:eventsDone?'Special-date policy and listed charges checked.':'Confirm whether special-date charges apply, then check each listed event.',done:eventsDone},
  {tab:'Rules',title:'Offers, upgrades and questions',detail:offersDone&&upgradesDone&&questionsDone?'Offers, room upgrades and questions checked.':'Check any offers or upgrades and resolve every open question.',done:offersDone&&upgradesDone&&questionsDone},
 ];
}
