 const filterPanel=(scope:string)=><>{scope==='desktop'&&<h3>Filter by</h3>}<label>Hotel name<input value={hotelText} onChange={e=>setHotelText(e.target.value)} placeholder="Search hotel name"/></label><fieldset><legend><Star size={16}/>Star category</legend>{[{n:3,label:'3 stars'},{n:4,label:'4 stars'},{n:5,label:'5 stars'},{n:-1,label:'Unclassified / no star class'},{n:0,label:'Not confirmed'}].map(({n,label})=><label className="ht-check" key={n}><input type="checkbox" checked={stars.includes(n)} onChange={e=>setStars(old=>e.target.checked?[...old,n]:old.filter(x=>x!==n))}/>{label}</label>)}</fieldset><fieldset><legend><Building2 size={16}/>Property type</legend>{(['hotel','resort','villa','apartment','guest_house','cabana','cabin','chalet','lodge','other','unknown'] as const).map(kind=><label className="ht-check" key={kind}><input type="checkbox" checked={propertyTypes.includes(kind)} onChange={e=>setPropertyTypes(old=>e.target.checked?[...old,kind]:old.filter(x=>x!==kind))}/>{propertyKindLabel(kind)}</label>)}</fieldset><fieldset><legend><Utensils size={16}/>Meal plan</legend>{[['BB','Breakfast'],['HB','Half board'],['FB','Full board'],['AI','All inclusive'],['RO','Room only']].map(([v,l])=><label className="ht-check" key={v}><input type="radio" name={'ht-plan-'+scope} checked={plan===v} onChange={()=>{setPlan(v);if(criteria)setCriteria({...criteria,plan:v as any})}}/>{v} · {l}</label>)}<p className="ht-hint">Prices follow each hotel’s contract. Meal adjustments are applied only when the contract lists and verifies them. A negative adjustment is a documented reduction.</p></fieldset><label>Room type<select value={roomFilter} onChange={e=>setRoomFilter(e.target.value)}><option value="">Any room</option>{roomOptions.map(r=><option key={r}>{r}</option>)}</select></label><label>Booking date<input type="date" value={bookingDate} onChange={e=>setBookingDate(e.target.value)}/></label><label>Maximum stay total (USD)<input type="number" min="0" step="1" value={budget} onChange={e=>setBudget(e.target.value)} placeholder="No limit"/></label><label className="ht-check"><input type="checkbox" checked={missing} onChange={e=>setMissing(e.target.checked)}/>Include rates needing checks</label><button className="ht-text" onClick={()=>{setStars([]);setPropertyTypes([]);setPlan('BB');setHotelText('');setRoomFilter('');setBudget('');setMissing(true);if(criteria)setCriteria({...criteria,plan:'BB'})}}>Clear filters</button></>;
